import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns

def perform_segmentation():
    # Load the data generated by your preprocessing script
    df = pd.read_csv('/Users/naitripanchal/E-commerce Sales & Customer Analytics with Churn Prediction /processed_rfm_data.csv')

    # 1. Calculate RFM Scores (1-5)
    # Higher Recency is bad, so we use labels [5, 4, 3, 2, 1]
    df['R_Score'] = pd.qcut(df['Recency'], 5, labels=[5, 4, 3, 2, 1])
    # Higher Frequency/Monetary is good, so we use [1, 2, 3, 4, 5]
    # Note: Frequency often has many 1s, so we use 'rank' to handle ties
    df['F_Score'] = pd.qcut(df['Frequency'].rank(method='first'), 5, labels=[1, 2, 3, 4, 5])
    df['M_Score'] = pd.qcut(df['Monetary'], 5, labels=[1, 2, 3, 4, 5])

    # Combine scores
    df['RFM_Score'] = df['R_Score'].astype(str) + df['F_Score'].astype(str) + df['M_Score'].astype(str)

    # 2. Define Customer Segments
    def segment_customer(row):
        score = int(row['R_Score']) + int(row['F_Score']) + int(row['M_Score'])
        if score >= 13:
            return 'Champions'
        elif score >= 10:
            return 'Loyal Customers'
        elif score >= 7:
            return 'At Risk'
        else:
            return 'Hibernating'

    df['Segment'] = df.apply(segment_customer, axis=1)

    # 3. Visualizing the Segments (Matches your Resume Point #3)
    plt.figure(figsize=(12, 6))
    sns.countplot(data=df, x='Segment', order=['Champions', 'Loyal Customers', 'At Risk', 'Hibernating'], palette='viridis')
    plt.title('Customer Segmentation Distribution')
    plt.savefig('customer_segments.png') # Save for GitHub README
    print("Segmentation complete. Image saved as 'customer_segments.png'")

    # Save the final segmented data
    df.to_csv('segmented_customers.csv', index=False)

if __name__ == "__main__":
    perform_segmentation()